96	/** Toolbar click handlers — extracted so `ReviewEditor` stays under the line-count cap. */
97	export const useToolbarHandlers = ({
98	  editor,
99	  maps,
100	  setters,
101	  setPending,
102	  onChange,
103	}: ToolbarHandlerDeps): ToolbarHandlers => {
104	  const openComposer = useCallback(
105	    (kind: "comment" | "insertion" | "replacement"): void => {
106	      const applied = applyAnnotation(editor, kind);
107	      if (applied === null) return;
108	      setPending({ kind, applied });
109	    },
110	    [editor, setPending]
111	  );
112	  const onCommentClick = useCallback((): void => openComposer("comment"), [openComposer]);
113	  const onInsertClick = useCallback((): void => openComposer("insertion"), [openComposer]);
114	  const onReplaceClick = useCallback((): void => openComposer("replacement"), [openComposer]);
115	  const onDeleteClick = useCallback((): void => {
116	    const applied = applyAnnotation(editor, "deletion");
117	    if (applied === null) {
118	      onChange?.(snapshotOf(editor, maps));
119	      return;
120	    }
121	    setters.setSuggestionOriginalTexts((prev) => new Map(prev).set(applied.id, applied.anchorText));
122	  }, [editor, maps, onChange, setters]);
123	  const triggerAnnotation = useCallback(
124	    (kind: AnnotationHandleKind): void => {
125	      if (kind === "comment") onCommentClick();
126	      else if (kind === "insertion") onInsertClick();
127	      else if (kind === "replacement") onReplaceClick();
128	      else onDeleteClick();
129	    },
130	    [onCommentClick, onInsertClick, onReplaceClick, onDeleteClick]
131	  );
132	  return { onCommentClick, onInsertClick, onReplaceClick, onDeleteClick, triggerAnnotation };
133	};
