135	/** Wire up the imperative `ReviewEditorHandle` and surface it through `onReady`. */
136	export const useReadyHandle = (
137	  editor: PlateEditor,
138	  maps: AnnotationMaps,
139	  removeAnnotation: ReviewEditorHandle["removeAnnotation"],
140	  updateAnnotation: ReviewEditorHandle["updateAnnotation"],
141	  triggerAnnotation: ReviewEditorHandle["triggerAnnotation"],
142	  onReady?: (h: ReviewEditorHandle) => void
143	): void => {
144	  useEffect(() => {
145	    onReady?.({
146	      hasValidSelection: () => hasValidSelection(editor),
147	      triggerAnnotation,
148	      getValue: () => editor.children,
149	      getCommentBodies: () => new Map(maps.bodies),
150	      getCommentImages: () => new Map(maps.images),
151	      getCommentOriginalTexts: () => new Map(maps.commentOriginalTexts),
152	      getSuggestionOriginalTexts: () => new Map(maps.suggestionOriginalTexts),
153	      getInsertionNewTexts: () => new Map(maps.insertionNewTexts),
154	      getInsertionImages: () => new Map(maps.insertionImages),
155	      getInsertionOriginalTexts: () => new Map(maps.insertionOriginalTexts),
156	      getReplacementTexts: () => new Map(maps.replacementTexts),
157	      getReplacementImages: () => new Map(maps.replacementImages),
158	      getReplacementOriginalTexts: () => new Map(maps.replacementOriginalTexts),
159	      removeAnnotation,
160	      updateAnnotation,
161	    });
162	  }, [editor, maps, removeAnnotation, updateAnnotation, triggerAnnotation, onReady]);
163	};
