340	/** Pending composer state plus its save / cancel handlers. */
341	export interface ComposerController {
342	  /** Authoring flow awaiting the composer's Save, or `null` when the composer is closed. */
343	  pending: PendingAuthoring | null;
344	  /** Opens the composer for a freshly-applied annotation; wired to {@link useToolbarHandlers}. */
345	  setPending: Dispatch<SetStateAction<PendingAuthoring | null>>;
346	  /** Persist the composer payload and close. */
347	  onComposerSave: (payload: AnnotationComposerPayload) => void;
348	  /** Close without saving; rolls the eager mark back synchronously in the dismiss event. */
349	  onComposerCancel: () => void;
350	}
351	
352	/**
353	 * Temporary diagnostic (symbiot#231): right after the synchronous cancel commit, record whether
354	 * the model was cleaned vs. what the DOM still shows, plus the focused element, on `window.__diag`.
355	 * The failing BDD step reads it back. Revert with the step-side instrumentation once confirmed.
356	 */
357	const recordCancelDiag = (editor: PlateEditor, pending: PendingAuthoring): void => {
358	  if (typeof document === "undefined") return;
359	  const w = window as unknown as { __diag?: unknown[] };
360	  const log = (w.__diag ??= []);
361	  const editorRoot = document.querySelector('[data-testid="editor-root"]');
362	  const snapshot = (ev: string): Record<string, unknown> => {
363	    const active = document.activeElement;
364	    return {
365	      ev,
366	      id: pending.applied.id,
367	      modelClean: !hasAnnotationMark(editor, pending.kind, pending.applied.id),
368	      domCount: document.querySelectorAll(`[data-testid="annotation-${pending.kind}"]`).length,
369	      activeTag: active ? active.tagName : null,
370	      activeTestId: active ? active.getAttribute("data-testid") : null,
371	      editorHasFocus: active !== null && editorRoot !== null && editorRoot.contains(active),
372	    };
373	  };
374	  log.push(snapshot("cancel"));
375	  // Focus-theory probe (symbiot#236): re-snapshot after the dismiss event settles and Radix
376	  // restores focus, to reveal WHERE focus lands per route (overlay click vs Cancel/Escape).
377	  setTimeout(() => log.push(snapshot("cancel+tick")), 0);
378	};
379	
380	/**
381	 * Own the inline composer's `pending` state and its save / cancel handlers.
382	 *
383	 * The eager "Pattern A" mark is rolled back **synchronously inside the cancel
384	 * event**, before the close commits and Radix's modal focus-restoration runs.
385	 * A deferred rollback (post-commit effect) races that focus restoration on the
386	 * overlay-dismiss route under CI load and intermittently leaves the highlight
387	 * behind (symbiot#231); running it in the handler closes the race.
388	 *
389	 * Save and cancel are already separate handlers: a save closes the dialog
390	 * programmatically (`open` → false), which does NOT fire Radix `onOpenChange`,
391	 * so it never reaches {@link onComposerCancel}; only genuine dismisses (button /
392	 * Escape / overlay click) do. `savedRef` still guards the rollback so that even
393	 * if a controlled close were to surface through `onOpenChange`, a just-saved mark
394	 * is kept; it is cleared whenever a fresh composer opens so a prior save never
395	 * suppresses the next cancel. `pendingRef` mirrors `pending` so the handler rolls
396	 * back the CURRENT id even when Radix invokes the callback from a stale render.
397	 * Extracted (like {@link useRemoveAnnotation}) so `ReviewEditor` stays under the
398	 * per-function line cap.
399	 */
400	export const useComposerController = (
401	  editor: PlateEditor,
402	  maps: AnnotationMaps,
403	  setters: PruneSetters,
404	  onChange?: (snapshot: EditorSnapshot) => void
405	): ComposerController => {
406	  const [pending, setPending] = useState<PendingAuthoring | null>(null);
407	  const pendingRef = useRef<PendingAuthoring | null>(null);
408	  const savedRef = useRef(false);
409	
410	  useEffect(() => {
411	    pendingRef.current = pending;
412	    if (pending !== null) savedRef.current = false;
413	  }, [pending]);
414	
415	  const onComposerSave = useCallback(
416	    (payload: AnnotationComposerPayload): void => {
417	      const { current } = pendingRef;
418	      if (current === null) return;
419	      dispatchComposerSave(current, payload, setters);
420	      savedRef.current = true;
421	      setPending(null);
422	    },
423	    [setters]
424	  );
425	
426	  const onComposerCancel = useCallback((): void => {
427	    if (savedRef.current) {
428	      savedRef.current = false;
429	      return;
430	    }
431	    const { current } = pendingRef;
432	    if (current === null) {
433	      setPending(null);
434	      return;
435	    }
436	    // Close the composer and roll the eager mark back in one synchronous commit. A React
437	    // re-render/remount does NOT clear the highlight on the blurred overlay-dismiss route
438	    // (symbiot#231 __diag: modelClean=true, domCount=1, editor blurred) — slate-react won't
439	    // reconcile the cleaned value into the blurred editor's DOM. Replacing the value with a
440	    // fresh array forces it to rebuild every leaf from the already-cleaned children.
441	    // eslint-disable-next-line @eslint-react/dom-no-flush-sync, n/no-sync -- synchronous commit before Radix focus restoration (symbiot#231)
442	    flushSync(() => {
443	      setPending(null);
444	      dispatchComposerCancel(current, editor, maps, onChange);
445	      editor.tf.setValue([...editor.children]);
446	    });
447	    recordCancelDiag(editor, current);
448	  }, [editor, maps, onChange]);
449	
450	  return { pending, setPending, onComposerSave, onComposerCancel };
451	};
