84	/**
85	 * Whether the composer is authoring a new annotation (`create`) or editing an
86	 * existing one (`edit`). Edit mode swaps in the per-kind {@link KindSurface.editTitle}
87	 * and surfaces a visible header so the reviewer knows they are changing an
88	 * existing note rather than adding one.
89	 */
90	export type AnnotationComposerMode = "create" | "edit";
91	
92	/**
93	 * Resolve the dialog header for a kind + mode: edit mode shows the edit title
94	 * and an always-visible header; the anchored create surfaces hide their header
95	 * (the quote carries the context) while `global` keeps it.
96	 */
97	const headerFor = (
98	  surface: KindSurface,
99	  kind: AnnotationComposerKind,
100	  mode: AnnotationComposerMode
101	): { title: string; hidden: boolean } => {
102	  const isEdit = mode === "edit";
103	  return {
104	    title: isEdit ? surface.editTitle : surface.title,
105	    hidden: !isEdit && kind !== "global",
106	  };
107	};
108	
109	interface AnnotationComposerProps {
110	  /** Which authoring surface to render. `global` omits the quote block. */
111	  kind: AnnotationComposerKind;
112	  open: boolean;
113	  /** Authoring vs. editing an existing annotation. Defaults to `create`. */
114	  mode?: AnnotationComposerMode;
115	  /** Selected text rendered as a quote above the textarea. Required unless `kind === "global"`. */
116	  quote?: string;
117	  /** Seeds the body when `mode === "edit"`; forwarded to `ComposerForm` and read once at mount. */
118	  initialBody?: string;
119	  /** Seeds the attached images when `mode === "edit"`; read once at mount. */
120	  initialImages?: AnnotationComposerPayload["images"];
121	  onSave: (payload: AnnotationComposerPayload) => void;
122	  onCancel: () => void;
123	}
124	
125	/**
126	 * Modal Dialog that captures a body + optional images either anchored to a
127	 * text selection (`kind`: `comment` / `insertion` / `replacement`) or floating
128	 * via the top-bar FAB (`kind`: `global`). Polymorphic over `kind` so the same
129	 * composer drives both selection-anchored and global-comment authoring; per-
130	 * kind testids keep existing Playwright selectors stable, while `data-mode`
131	 * lets edit-mode hosts target the reused dialog without new testids.
132	 */
133	export const AnnotationComposer = ({
134	  kind,
135	  open,
136	  mode = "create",
137	  quote,
138	  initialBody,
139	  initialImages,
140	  onSave,
141	  onCancel,
142	}: AnnotationComposerProps): React.ReactElement => {
143	  const surface = kindSurface[kind];
144	  const onOpenChange = useCallback(
145	    (next: boolean): void => {
146	      if (!next) onCancel();
147	    },
148	    [onCancel]
149	  );
150	
151	  // Make the overlay-click dismiss mirror the reliable Cancel-button route (symbiot#236). The
152	  // eager-highlight rollback survives ONLY on the overlay route because that route runs onCancel
153	  // from Radix's native pointerdown listener, while Cancel/Escape run it inside a React synthetic
154	  // event where slate-react reconciles the blurred read-only editor. So: suppress Radix's native
155	  // outside-dismiss (onPointerDownOutside preventDefault) and instead dismiss from a React onClick
156	  // on the backdrop, and keep the mousedown from blurring the textarea to <body>. The overlay then
157	  // matches the Cancel button in both event origin and focus.
158	  const suppressNativeOutsideDismiss = useCallback((event: Event): void => {
159	    event.preventDefault();
160	  }, []);
161	  const keepFocusOnOverlayPress = useCallback((event: MouseEvent): void => {
162	    event.preventDefault();
163	  }, []);
164	  const dismissFromOverlayClick = useCallback((): void => {
165	    onCancel();
166	  }, [onCancel]);
167	
168	  const showQuote = kind !== "global" && typeof quote === "string";
169	  const header = headerFor(surface, kind, mode);
170	
171	  return (
172	    <Dialog open={open} onOpenChange={onOpenChange}>
173	      <DialogContent
174	        data-testid={surface.testIds.composer}
175	        data-kind={kind}
176	        data-mode={mode}
177	        className="sm:max-w-2xl"
178	        onPointerDownOutside={suppressNativeOutsideDismiss}
179	        overlayProps={{ onMouseDown: keepFocusOnOverlayPress, onClick: dismissFromOverlayClick }}
180	      >
181	        <DialogHeader className={header.hidden ? "sr-only" : undefined}>
182	          <DialogTitle>{header.title}</DialogTitle>
183	          <DialogDescription>{surface.description}</DialogDescription>
184	        </DialogHeader>
185	        {showQuote ? (
186	          <blockquote
187	            data-testid="composer-quote"
188	            className={`line-clamp-4 rounded-sm border-l-2 py-1 pl-3 text-sm whitespace-pre-wrap italic ${surface.quoteClass}`}
189	          >
190	            {quote}
191	          </blockquote>
192	        ) : null}
193	        <ComposerForm
194	          open={open}
195	          placeholder={surface.placeholder}
196	          onSave={onSave}
197	          onCancel={onCancel}
198	          testId={surface.testIds.form}
199	          initialBody={initialBody}
200	          initialImages={initialImages}
201	        />
202	      </DialogContent>
203	    </Dialog>
204	  );
205	};
