1	import type { PlateEditor } from "platejs/react";
2	
3	import { type AnnotationKind, prefixOf } from "./annotationKind.ts";
4	
5	interface TextLeaf {
6	  text: string;
7	  [mark: string]: unknown;
8	}
9	
10	const isTextLeaf = (node: unknown): node is TextLeaf =>
11	  typeof (node as { text?: unknown }).text === "string";
12	
13	const collectMatchingPaths = (
14	  nodes: readonly unknown[],
15	  idKey: string,
16	  path: number[],
17	  out: { leaf: TextLeaf; path: number[] }[]
18	): void => {
19	  nodes.forEach((node, index) => {
20	    const here = [...path, index];
21	    if (isTextLeaf(node)) {
22	      if (node[idKey] === true) out.push({ leaf: node, path: here });
23	      return;
24	    }
25	    const { children } = node as { children?: unknown[] };
26	    if (Array.isArray(children)) collectMatchingPaths(children, idKey, here, out);
27	  });
28	};
29	
30	const hasSiblingIdMark = (leaf: TextLeaf, prefix: string, idKey: string): boolean => {
31	  for (const key of Object.keys(leaf)) {
32	    if (key === idKey) continue;
33	    if (key.startsWith(`${prefix}_`) && leaf[key] === true) return true;
34	  }
35	  return false;
36	};
37	
38	/**
39	 * Unset the `comment_<id>` (or `suggestion_<id>`) mark from every text leaf
40	 * in the editor value, and also drop the umbrella `comment` / `suggestion`
41	 * mark on any leaf that no longer carries another sibling id mark. Mirrors
42	 * `applyComment` / `applyDeletion` (which add the same two marks together).
43	 */
44	export const removeAnnotationMark = (
45	  editor: PlateEditor,
46	  kind: AnnotationKind,
47	  id: string
48	): void => {
49	  const prefix = prefixOf(kind);
50	  const idKey = `${prefix}_${id}`;
51	  const matches: { leaf: TextLeaf; path: number[] }[] = [];
52	  collectMatchingPaths(editor.children, idKey, [], matches);
53	
54	  for (const { leaf, path } of matches) {
55	    editor.tf.unsetNodes(idKey, { at: path });
56	    if (!hasSiblingIdMark(leaf, prefix, idKey)) {
57	      editor.tf.unsetNodes(prefix, { at: path });
58	    }
59	  }
60	};
61	
62	/** Whether any text leaf in the editor value still carries the `<prefix>_<id>` mark. */
63	export const hasAnnotationMark = (
64	  editor: PlateEditor,
65	  kind: AnnotationKind,
66	  id: string
67	): boolean => {
68	  const idKey = `${prefixOf(kind)}_${id}`;
69	  const matches: { leaf: TextLeaf; path: number[] }[] = [];
70	  collectMatchingPaths(editor.children, idKey, [], matches);
71	  return matches.length > 0;
72	};
