18	import { Then } from "../support/bdd.ts";
19	
20	/** Maps a selection-toolbar annotation kind to the `data-testid` its leaf renders with. */
21	const highlightTestIdByKind: Record<string, string> = {
22	  comment: "annotation-comment",
23	  insertion: "annotation-insertion",
24	  replacement: "annotation-replacement",
25	};
26	
27	/** Resolve the editor-scoped locator for a kind's highlight, failing loudly on an unknown kind. */
28	const highlightLocator = (page: Page, kind: string): Locator => {
29	  const testId = highlightTestIdByKind[kind];
30	  if (testId === undefined) {
31	    throw new Error(
32	      `Unknown annotation kind "${kind}" — expected one of ${Object.keys(highlightTestIdByKind).join(", ")}`
33	    );
34	  }
35	  return page.getByTestId("editor-root").getByTestId(testId);
36	};
