38	Then("the {string} highlight is visible in the editor", async ({ page }, kind: string) => {
39	  await expect(highlightLocator(page, kind).first()).toBeVisible();
40	});
41	
42	Then("the {string} highlight is absent from the editor", async ({ page }, kind: string) => {
43	  const readDiag = async (): Promise<string> =>
44	    page.evaluate(() =>
45	      JSON.stringify((window as unknown as { __diag?: unknown[] }).__diag ?? null)
46	    );
47	  try {
48	    await expect(highlightLocator(page, kind)).toHaveCount(0);
49	  } catch (error) {
50	    // Temporary diagnostic (symbiot#231): dump the editor's per-cancel record so a flaky
51	    // failure shows whether the model was cleaned and what the DOM held. Revert with the
52	    // editor-side instrumentation once the mechanism is confirmed.
53	    throw new Error(`[symbiot#231] highlight not absent. __diag=${await readDiag()}`, {
