// @vitest-environment happy-dom
/**
 * Mounted-editor coverage for {@link scrubOrphanedPendingHighlight}: the guard
 * chain and the DOM strip must work against a real `<PlateContent>` mount, not
 * just headless editors — the CI probe showed the scrub bailing in the browser.
 */
import { render } from "@testing-library/react";
import { Plate, PlateContent, usePlateEditor, type PlateEditor } from "platejs/react";
import { describe, expect, it } from "vitest";

import { SymbiotEditorKit } from "./kit.ts";
import { scrubOrphanedPendingHighlight } from "./pendingHighlight.ts";

interface HostProps {
  onEditor: (editor: PlateEditor) => void;
}

const Host = ({ onEditor }: HostProps): React.ReactElement => {
  const editor = usePlateEditor({
    plugins: SymbiotEditorKit,
    value: [{ type: "p", children: [{ text: "hello world" }] }],
  });
  onEditor(editor);
  return (
    <Plate editor={editor}>
      <PlateContent readOnly />
    </Plate>
  );
};

describe("scrubOrphanedPendingHighlight (mounted)", () => {
  it("scrubs an orphaned mark inside the live editable", () => {
    let editor: PlateEditor | undefined;
    render(<Host onEditor={(e) => (editor = e)} />);
    const editable = editor!.api.toDOMNode(editor!);
    expect(editable).toBeDefined();
    const orphan = document.createElement("mark");
    orphan.setAttribute("data-testid", "annotation-comment");
    orphan.setAttribute("class", "text-anno-comment");
    orphan.textContent = "orphan";
    editable!.append(orphan);

    expect(scrubOrphanedPendingHighlight(editor!, "comment")).toBe("scrubbed");
    expect(document.querySelectorAll('[data-testid="annotation-comment"]')).toHaveLength(0);
    expect(orphan.textContent).toBe("orphan");
  });
});

