    at: [],
    match: (node) => TextApi.isText(node) && node[prefix] === true,
  });
  if (!marked.next().done) return "model-marked";
  let editable: HTMLElement | undefined;
  try {
    editable = editor.api.toDOMNode(editor);
  } catch {
    // Some slate-react versions throw instead of returning undefined here.
    editable = undefined;
  }
  if (editable !== undefined) {
    scrubAnnotationDom(editable, kind);
    return "scrubbed";
  }
  // The editor→DOM registry can be unavailable mid-teardown — and on the flaky CI
  // repeats slate's own bookkeeping is exactly what misbehaves — so fall back to
  // the host container. The guards above already proved any match is orphaned;
  // the review editor is the only surface rendering `annotation-<kind>` marks.
  const container = document.querySelector('[data-testid="editor-root"]');
  if (container === null) return "no-dom";
  scrubAnnotationDom(container, kind);
  return "scrubbed-fallback";
};

