9	import { fixturePlanSlug, fixtureProjectSlug } from "./testAssets.ts";
10	import { repoRoot } from "./world.ts";
11	
12	/**
13	 * Per-worker viewer infrastructure for the parallel BDD suite.
14	 *
15	 * Playwright's `webServer` block is global — one set of servers shared by every
16	 * worker — so it cannot isolate the mutable state (decision files, `~/.symbiot`
17	 * history/drafts) that concurrent scenarios collide on. Instead each worker boots
18	 * its OWN plan / annotate / no-heading viewers via a worker-scoped fixture (see
19	 * {@link ./bdd.ts}), each on an OS-assigned port with a private `HOME` and private
20	 * decision files. OS-assigned ports (the viewer binds `port ?? 0`) are collision-proof
21	 * by construction — the kernel never hands two listeners the same free port — which
22	 * is why this does not shard ports by worker index.
23	 *
24	 * @example
25	 * ```ts
26	 * const worker = await startWorkerViewers();
27	 * // worker.instances.planUrl → "http://127.0.0.1:<port>/"
28	 * await worker.stop();
29	 * ```
30	 */
31	
32	/** Markdown plan booted by the plan + annotate viewers (carries every supported element). */
33	const planPath = join(repoRoot, "fixtures", "markdown", "elements.md");
34	/** Headingless plan booted by the no-heading viewer so the no-H1 document-title fallback is exercised. */
35	const noHeadingPlanPath = join(repoRoot, "fixtures", "markdown", "no-heading.md");
36	/** Viewer CLI entrypoint spawned once per mode, per worker. */
37	const viewerBin = join(repoRoot, "apps", "viewer", "src", "bin.ts");
38	/** Prefix for each worker's throwaway `HOME` under the OS temp dir; teardown removes its own dir. */
39	const homePrefix = join(tmpdir(), "symbiot-bdd-w-");
40	
41	/** How long a single viewer gets to print its listening URL and answer `/api/plan`. */
42	const bootTimeoutMs = 30_000;
43	/** Matches the `symbiot viewer listening at http://127.0.0.1:<port>/` line the viewer prints on boot. */
44	const listeningRe = /listening at (http:\/\/127\.0\.0\.1:\d+\/)/;
45	
46	/** Resolved URLs + per-worker state paths handed to the worker-scoped `viewers` fixture. */
47	export interface ViewerInstances {
48	  /** Plan-mode viewer (Approve / Deny) — also the suite's `baseURL`. */
49	  planUrl: string;
50	  /** Annotate-mode viewer (Submit feedback). */
51	  annotateUrl: string;
52	  /** Headingless-plan viewer for the document-title no-H1 fallback. */
53	  noHeadingUrl: string;
54	  /** This worker's isolated `HOME`; `~/.symbiot` state lives under here. */
55	  home: string;
56	  /** Where the plan-mode viewer writes each Approve/Deny decision. */
57	  planDecisionFile: string;
58	  /** Where the annotate-mode viewer writes each Submit-feedback decision. */
59	  annotateDecisionFile: string;
60	}
61	
62	/** A worker's running viewers plus the teardown that kills them and removes its `HOME`. */
63	export interface WorkerViewers {
64	  instances: ViewerInstances;
65	  stop: () => Promise<void>;
66	}
67	
68	interface SpawnedViewer {
69	  child: ChildProcess;
70	  url: string;
71	}
72	
73	/** Resolve once the child prints its listening URL; reject if it exits first or times out. */
74	const waitForListening = async (child: ChildProcess, label: string): Promise<string> => {
75	  let url: string | null = null;
76	  let stderr = "";
77	  let ended = false;
78	  child.stderr?.on("data", (chunk: Buffer) => {
79	    stderr += chunk.toString("utf8");
80	  });
81	  // A line reader stays attached for the child's lifetime so stdout keeps draining
82	  // and the OS pipe buffer never fills under `--keep-alive`.
83	  const reader = createInterface({ input: child.stdout! });
84	  reader.on("line", (line: string) => {
85	    const [, captured] = listeningRe.exec(line) ?? [];
86	    if (captured !== undefined) url = captured;
87	  });
88	  child.on("exit", () => {
89	    ended = true;
90	  });
91	  child.on("error", () => {
92	    ended = true;
93	  });
94	  await expect
95	    .poll(() => url !== null || ended, {
96	      timeout: bootTimeoutMs,
97	      message: `${label} viewer did not print a listening URL within ${bootTimeoutMs}ms`,
98	    })
99	    .toBe(true);
100	  if (url === null) throw new Error(`${label} viewer exited before listening\n${stderr}`);
101	  return url;
102	};
103	
104	/** Poll `<url>api/plan` until it answers OK, so a worker never starts tests against a half-booted viewer. */
105	const waitForHttpReady = async (url: string, label: string): Promise<void> => {
106	  await expect
107	    .poll(
108	      async (): Promise<boolean> => {
109	        try {
110	          return (await fetch(`${url}api/plan`)).ok;
111	        } catch {
112	          return false;
113	        }
114	      },
115	      { timeout: bootTimeoutMs, message: `${label} viewer never answered /api/plan` }
116	    )
117	    .toBe(true);
118	};
119	
120	/** SIGTERM a viewer and resolve once it has exited (the viewer's keep-alive loop handles SIGTERM). */
121	const killViewer = (child: ChildProcess): Promise<void> => {
122	  if (child.exitCode !== null || child.signalCode !== null) return Promise.resolve();
123	  return new Promise<void>((resolve) => {
124	    child.once("exit", () => resolve());
125	    child.kill("SIGTERM");
126	  });
127	};
128	
129	const spawnViewer = async (
130	  home: string,
131	  plan: string,
132	  mode: "plan" | "annotate",
133	  decisionFile: string | null,
134	  label: string
135	): Promise<SpawnedViewer> => {
136	  const args = [viewerBin, "--plan", plan, "--no-open", "--keep-alive", "--mode", mode];
137	  if (decisionFile !== null) args.push("--decision-file", decisionFile);
138	  const child = spawn("bun", args, {
139	    cwd: repoRoot,
140	    env: { ...process.env, HOME: home },
141	    stdio: ["ignore", "pipe", "pipe"],
142	  });
143	  try {
144	    const url = await waitForListening(child, label);
145	    await waitForHttpReady(url, label);
146	    return { child, url };
147	  } catch (error) {
148	    // Readiness failed before the caller could track this child for teardown —
149	    // kill it here so a failed boot never leaks a viewer process.
150	    await killViewer(child);
151	    throw error;
152	  }
153	};
154	
155	/**
156	 * Boot one worker's plan / annotate / no-heading viewers under a fresh `HOME`,
157	 * seeding the predecessor `001.md` so the plan viewer boots as version `002.md`
158	 * (what `predecessor-diff.feature` asserts against). Transactional: any failure
159	 * tears down whatever already started and removes the `HOME` before rethrowing,
160	 * because Playwright skips fixture teardown when setup throws before yielding.
161	 */
162	export const startWorkerViewers = async (): Promise<WorkerViewers> => {
163	  const home = await mkdtemp(homePrefix);
164	  const started: ChildProcess[] = [];
165	  const cleanup = async (): Promise<void> => {
166	    await Promise.all(started.map(killViewer));
167	    await rm(home, { recursive: true, force: true });
168	  };
169	  try {
170	    const historyDir = join(
171	      home,
172	      ".symbiot",
173	      "agents",
174	      "claude-code",
175	      "history",
176	      fixtureProjectSlug,
177	      fixturePlanSlug
178	    );
179	    await mkdir(historyDir, { recursive: true });
180	    await cp(planPath, join(historyDir, "001.md"));
181	
182	    const planDecisionFile = join(home, "last-decision.json");
183	    const annotateDecisionFile = join(home, "annotate-decision.json");
184	
185	    const plan = await spawnViewer(home, planPath, "plan", planDecisionFile, "plan");
186	    started.push(plan.child);
187	    const annotate = await spawnViewer(
188	      home,
189	      planPath,
190	      "annotate",
191	      annotateDecisionFile,
192	      "annotate"
193	    );
194	    started.push(annotate.child);
195	    const noHeading = await spawnViewer(home, noHeadingPlanPath, "plan", null, "no-heading");
196	    started.push(noHeading.child);
197	
198	    return {
199	      instances: {
200	        planUrl: plan.url,
201	        annotateUrl: annotate.url,
202	        noHeadingUrl: noHeading.url,
203	        home,
204	        planDecisionFile,
205	        annotateDecisionFile,
206	      },
207	      stop: cleanup,
208	    };
209	  } catch (error) {
210	    await cleanup();
211	    throw error;
212	  }
213	};
