/**
 * Temporary diagnostic (symbiot#231): every model text leaf carrying the kind's
 * umbrella mark — the keys reveal WHO wrote it (saved id / draft key / residue).
 */
const markedLeavesOf = (editor: PlateEditor, kind: PendingAuthoring["kind"]): unknown[] => {
  const found: unknown[] = [];
  const walk = (nodes: readonly unknown[]): void => {
    for (const node of nodes) {
      const leaf = node as { text?: unknown; children?: unknown[] };
      if (typeof leaf.text === "string") {
        const record = node as Record<string, unknown>;
        if (record[kind] === true) {
          found.push({
            text: leaf.text.slice(0, 24),
            keys: Object.keys(record).filter((key) => key !== "text"),
          });
        }
      } else if (Array.isArray(leaf.children)) {
        walk(leaf.children);
      }
    }
  };
  walk(editor.children);
  return found;
};

/** Temporary diagnostic (symbiot#231): capture-time model state, to date the marked leaf. */
